-- Revenue & Sales Performance

-- 1. What is the total revenue generated by the business?
select 
    sum(Total_amount) as Total_revenue
from files.order_items;

-- 2. What is the Average Order Value (AOV), and how does it change over time?
select
    date_format(order_date, '%Y-%m') as month,
    avg(order_revenue) as AOV
from (
    select
        o.order_id,
        o.order_date,
        sum(oi.total_amount) as order_revenue
    from files.orders o
    join files.order_items oi
        on o.order_id = oi.order_id
    group by
        o.order_id,
        o.order_date
) t
group by month
order by month;

-- 3. What is the revenue generated each month?
 SELECT
    DATE_FORMAT(o.order_date, '%Y-%m') AS month,
    SUM(oi.total_amount) AS monthly_revenue
FROM files.orders o
JOIN files.order_items oi
    ON o.order_id = oi.order_id
GROUP BY DATE_FORMAT(o.order_date, '%Y-%m')
ORDER BY month;

-- 4. Which months had the highest revenue growth and decline?
with monthly_sales as (
select
    date_format(o.order_date, '%Y-%m') AS month,
    sum(oi.total_amount) AS monthly_revenue
from files.orders o
join files.order_items oi
    on o.order_id = oi.order_id
group by date_format(o.order_date, '%Y-%m')
),
monthly_growth as (
select 
   month, 
   monthly_revenue,
   lag(monthly_revenue) over(order by month) as previous_month_revenue
from monthly_sales
)
select
    month,
    monthly_revenue,
    previous_month_revenue,
    round(
        (monthly_revenue - previous_month_revenue)
        / previous_month_revenue * 100,
        2
    ) as growth_percentage
from monthly_growth
order by month;

-- Customer Analysis

-- 5. What is the Customer Lifetime Value (CLV) for each customer?
select
   customer_id,
   sum(oi.total_amount) as CLV
from files.orders o 
join files.order_items oi 
   on o.order_id = oi.order_id
group by customer_id;

-- 6. Who are the Top 10 customers by total spending?
select
   customer_id,
   sum(oi.total_amount) as total_spending
from files.orders o 
join files.order_items oi 
   on o.order_id = oi.order_id
group by customer_id
order by customer_id desc 
limit 10;

-- 7. List of the customers who has placed the repeated orders.
select
   customer_id,
   count(order_id) as number_of_orders
from files.orders
group by customer_id
having count(order_id) > 1
order by number_of_orders desc;

-- 8. What percentage of total revenue is generated by the Top 10% of customers?
with customer_sales as (
    select
        o.customer_id,
        sum(oi.total_amount) as total_spending
    from files.orders o
    join files.order_items oi
        on o.order_id = oi.order_id
    group by o.customer_id
),
customer_groups as (
    select
        customer_id,
        total_spending,
        ntile(10) over (order by total_spending desc) as customer_group
    from customer_sales
)
select
    round(
        sum(case when customer_group = 1 then total_spending else 0 end) / sum(total_spending) * 100,
        2
    ) as top_10_percent_revenue_contribution
from customer_groups;

-- Product & Category Performance

-- 9. Which product categories generate the highest revenue, and what percentage of total revenue does each category contribute?
select 
    p.category,
    sum(oi.total_amount) as total_revenue,
    round(
        sum(oi.total_amount) * 100 /
        (select sum(total_amount) from files.order_items),
        2) as revenue_percentage
from files.products p
join files.order_items oi 
    on p.product_id = oi.product_id
group by p.category
order by total_revenue desc;

-- 10. Which products generate the highest revenue?
select 
   p.product_id,
   sum(total_amount) as total_revenue
from files.products p
join files.order_items oi
   on p.product_id = oi.product_id
group by p.product_id
order by total_revenue desc;

-- 11. Which products have the highest quantity sold?
select 
   p.product_id,
   sum(oi.quantity) as quantity_sold
from files.products p
join files.order_items oi
   on p.product_id - oi.product_id
group by p.product_id
order by quantity_sold desc;

-- Q12. What are the Top 3 revenue-generating products within each category?
with product_revenue as (
select 
   category,
   p.product_id,
   sum(Total_Amount) as total_revenue
from files.products p 
join files.order_items oi 
   on p.product_id = oi.product_id
group by 
   category, 
   p.product_id
),
ranked_revenue as (
select 
   category,
   product_id,
   total_revenue,
   row_number() over(partition by category order by total_revenue desc) as product_rank
from product_revenue
)
select 
   category,
   product_id,
   total_revenue,
   product_rank
from ranked_revenue
where product_rank <= 3
order by category, product_rank;

-- Market / City Performance

-- Q13. Which cities generate the highest revenue, and how does revenue per customer compare across cities?
select 
    c.city,
    sum(oi.total_amount) as total_revenue,
    count(distinct o.customer_id) as total_customers,
    round(
        sum(oi.total_amount) / count(distinct o.customer_id),
        2
    ) as revenue_per_customer
from files.orders o
join files.order_items oi
    on o.order_id = oi.order_id
join files.customers c
    on o.customer_id = c.customer_id
group by c.city
order by total_revenue desc;

-- Payment Performance

-- Q14. Which payment methods are most frequently used, and what is the payment success rate for each method?
select
   payment_method,
   count(*) as total_payments,
   sum(case 
         when status = 'Success' then 1 else 0 end) as successful_payments,
   round(sum(
       case when status = 'Success' then 1 else 0 end) * 100.0 
       / count(*),2) as success_rate
from files.payments
group by payment_method
order by total_payments desc;

-- Q15. Which payment method has the highest Average Order Value?
select
    p.payment_method,
    round(
        sum(oi.total_amount) / count(distinct o.order_id),
        2) AS average_order_value
from files.orders o
join files.order_items oi
    on o.order_id = oi.order_id
join files.payments p
    on o.order_id = p.order_id
group by p.payment_method
order by average_order_value desc;
   
